SELECT o.id, c.name, s.status, p.amount, r.rate, w.note FROM orders AS o JOIN customers AS c ON c.id = o.customer_id LEFT JOIN shipments AS s ON s.order_id = o.id RIGHT OUTER JOIN payments AS p ON p.order_id = o.id FULL OUTER JOIN refunds AS rf ON rf.order_id = o.id ASOF LEFT JOIN fx_rates AS r ON r.currency = o.currency AND r.valid_from <= o.created_at LEFT OUTER JOIN warehouse_notes AS w ON w.order_id = o.id
